/*
Theme Name: Block Editor Creator Lab
Theme URI: https://github.com/wordpress/blueprints
Author: fellyph
Description: A bold block theme for a WordPress Block Editor learning blueprint.
Version: 1.0.0
Requires at least: 6.6
Tested up to: 6.9
Requires PHP: 7.2
License: GNU General Public License v2 or later
License URI: https://www.gnu.org/licenses/gpl-2.0.html
Text Domain: block-editor-creator-lab
*/
:root {
	--lab-ink: #111111;
	--lab-paper: #fbfaf5;
	--lab-white: #ffffff;
	--lab-cyan: #00c7ff;
	--lab-lime: #b8ff32;
	--lab-coral: #ff4f6d;
	--lab-yellow: #ffd33d;
	--lab-blue: #2458ff;
	--lab-line: #111111;
	--lab-muted: #5b5b54;
	--lab-shadow: 8px 8px 0 var(--lab-ink);
}
html {
	scroll-behavior: smooth;
}
body {
	margin: 0;
	background: var(--lab-paper);
	color: var(--lab-ink);
	font-family: Avenir Next, Trebuchet MS, Verdana, sans-serif;
	font-size: 18px;
	line-height: 1.55;
}
a {
	color: inherit;
	text-decoration-thickness: 0.12em;
	text-underline-offset: 0.18em;
}
.lab-site-header,
.lab-site-footer {
	box-sizing: border-box;
	width: min(1180px, calc(100% - 32px));
	margin: 16px auto;
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	background: var(--lab-white);
	box-shadow: 4px 4px 0 var(--lab-line);
}
.lab-site-header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16px;
	padding: 12px 14px;
}
.lab-brand,
.lab-admin-link,
.lab-footer-link {
	font-weight: 900;
	text-decoration: none;
}
.lab-brand {
	display: inline-flex;
	align-items: center;
	gap: 10px;
	font-size: clamp(1rem, 2.5vw, 1.2rem);
	letter-spacing: 0;
}
.lab-brand::before {
	content: '';
	width: 18px;
	height: 18px;
	border: 2px solid var(--lab-line);
	background: var(--lab-lime);
	box-shadow: 4px 4px 0 var(--lab-cyan);
}
.lab-admin-link,
.lab-footer-link {
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	padding: 8px 12px;
	background: var(--lab-yellow);
	box-shadow: 3px 3px 0 var(--lab-line);
}
.lab-site-footer {
	padding: 18px;
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16px;
	font-size: 0.95rem;
	color: var(--lab-muted);
}
.lab-template,
.lab-index-template {
	margin: 0 auto;
}
.creator-lab {
	box-sizing: border-box;
	width: min(1180px, calc(100% - 32px));
	margin: 20px auto 64px;
}
.lab-hero {
	position: relative;
	isolation: isolate;
	overflow: hidden;
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	background: var(--lab-ink);
	color: var(--lab-white);
	box-shadow: var(--lab-shadow);
	padding: clamp(28px, 6vw, 76px);
}
.lab-hero::after {
	content: '';
	position: absolute;
	inset: auto -20px -36px auto;
	width: min(320px, 58vw);
	height: 150px;
	background: repeating-linear-gradient(135deg, var(--lab-cyan) 0 14px, var(--lab-lime) 14px 28px, var(--lab-coral) 28px 42px, var(--lab-yellow) 42px 56px);
	border: 2px solid var(--lab-line);
	transform: rotate(-6deg);
	z-index: -1;
}
.lab-kicker,
.step-label,
.lane-label,
.lab-tag {
	margin: 0;
	font-size: 0.78rem;
	font-weight: 900;
	letter-spacing: 0;
	text-transform: uppercase;
}
.lab-kicker,
.lab-tag {
	display: inline-flex;
	width: fit-content;
	border: 2px solid var(--lab-line);
	border-radius: 999px;
	background: var(--lab-lime);
	color: var(--lab-ink);
	padding: 6px 10px;
}
.lab-hero h1 {
	max-width: 850px;
	margin: 20px 0 14px;
	font-family: Impact, Haettenschweiler, Arial Black, sans-serif;
	font-size: clamp(3rem, 9vw, 7.4rem);
	line-height: 0.9;
	font-weight: 900;
	letter-spacing: 0;
	text-transform: uppercase;
}
.lab-lede {
	max-width: 760px;
	margin: 0;
	font-size: clamp(1.1rem, 2.5vw, 1.45rem);
	font-weight: 700;
	color: #f5f5f0;
}
.lab-actions {
	display: flex;
	flex-wrap: wrap;
	gap: 12px;
	margin-top: 28px;
}
.lab-button {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-height: 44px;
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	padding: 10px 14px;
	background: var(--lab-white);
	box-shadow: 4px 4px 0 var(--lab-line);
	color: var(--lab-ink);
	font-weight: 900;
	text-decoration: none;
	transition: transform 140ms ease, box-shadow 140ms ease;
}
.lab-button.primary {
	background: var(--lab-cyan);
}
.lab-button.page {
	background: var(--lab-yellow);
}
.lab-button:hover,
.lab-button:focus-visible,
.lab-admin-link:hover,
.lab-admin-link:focus-visible,
.lab-footer-link:hover,
.lab-footer-link:focus-visible {
	transform: translate(2px, 2px);
	box-shadow: 2px 2px 0 var(--lab-line);
}
.lesson-switch {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 12px;
	margin: 28px 0;
}
.lesson-pill {
	display: grid;
	grid-template-columns: auto 1fr;
	align-items: center;
	gap: 10px;
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	padding: 12px;
	background: var(--lab-white);
	box-shadow: 4px 4px 0 var(--lab-line);
	font-weight: 900;
	text-decoration: none;
}
.lesson-pill span {
	display: inline-grid;
	place-items: center;
	width: 34px;
	height: 34px;
	border: 2px solid var(--lab-line);
	border-radius: 50%;
	background: var(--lab-lime);
}
.lesson-pill.is-active {
	background: var(--lab-ink);
	color: var(--lab-white);
}
.lesson-pill.is-active span {
	background: var(--lab-coral);
	color: var(--lab-white);
}
.lab-section {
	margin: 34px 0;
}
.lab-section-header {
	display: flex;
	align-items: end;
	justify-content: space-between;
	gap: 18px;
	margin-bottom: 16px;
}
.lab-section h2 {
	margin: 0;
	font-family: Impact, Haettenschweiler, Arial Black, sans-serif;
	font-size: clamp(2rem, 5vw, 4.2rem);
	line-height: 0.95;
	letter-spacing: 0;
	text-transform: uppercase;
}
.lab-section-intro {
	max-width: 620px;
	margin: 8px 0 0;
	color: var(--lab-muted);
	font-weight: 700;
}
.step-grid {
	display: grid;
	grid-template-columns: repeat(4, minmax(0, 1fr));
	gap: 14px;
}
.step-card,
.lab-callout,
.creator-panel,
.lane-card {
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	background: var(--lab-white);
	box-shadow: 5px 5px 0 var(--lab-line);
}
.step-card {
	padding: 18px;
}
.step-card:nth-child(1) {
	background: var(--lab-yellow);
}
.step-card:nth-child(2) {
	background: var(--lab-cyan);
}
.step-card:nth-child(3) {
	background: var(--lab-lime);
}
.step-card:nth-child(4) {
	background: var(--lab-coral);
	color: var(--lab-white);
}
.step-label {
	display: inline-flex;
	border: 2px solid var(--lab-line);
	border-radius: 999px;
	padding: 4px 8px;
	background: var(--lab-white);
	color: var(--lab-ink);
}
.step-card h3,
.lane-card h3,
.creator-panel h3 {
	margin: 14px 0 8px;
	font-size: clamp(1.25rem, 2.5vw, 1.65rem);
	line-height: 1.05;
}
.step-card p,
.lane-card p,
.creator-panel p,
.lab-callout p {
	margin: 0;
	font-weight: 700;
}
.lab-callout {
	display: grid;
	grid-template-columns: 0.55fr 1fr;
	gap: 20px;
	padding: 22px;
	background: var(--lab-ink);
	color: var(--lab-white);
}
.lab-callout strong {
	color: var(--lab-lime);
}
.lane-grid {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 14px;
}
.lane-card {
	padding: 18px;
}
.lane-label {
	color: var(--lab-blue);
}
.creator-panel {
	padding: clamp(20px, 4vw, 34px);
	background: repeating-linear-gradient(90deg, #ffffff 0 16px, #f0f0ea 16px 32px);
}
.creator-panel h3 {
	font-family: Impact, Haettenschweiler, Arial Black, sans-serif;
	font-size: clamp(2rem, 4vw, 3.4rem);
	text-transform: uppercase;
}
.checklist {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 10px;
	margin: 18px 0 0;
	padding: 0;
	list-style: none;
}
.checklist li {
	border: 2px solid var(--lab-line);
	border-radius: 8px;
	background: var(--lab-white);
	padding: 12px;
	font-weight: 900;
}
.checklist li::before {
	content: 'OK';
	display: inline-flex;
	margin-right: 8px;
	border: 2px solid var(--lab-line);
	border-radius: 4px;
	background: var(--lab-lime);
	padding: 1px 5px;
	font-size: 0.75rem;
}
.lab-index-template {
	box-sizing: border-box;
	width: min(1180px, calc(100% - 32px));
}
@media (max-width: 860px) {
	.lab-site-header,
	.lab-site-footer,
	.lab-section-header,
	.lab-callout {
		align-items: stretch;
		grid-template-columns: 1fr;
		flex-direction: column;
	}
	.lesson-switch,
	.step-grid,
	.lane-grid,
	.checklist {
		grid-template-columns: 1fr;
	}
	.lab-hero {
		padding: 28px 20px 42px;
	}
	.lab-site-footer {
		display: grid;
	}
}
@media (max-width: 520px) {
	body {
		font-size: 16px;
	}
	.creator-lab,
	.lab-site-header,
	.lab-site-footer,
	.lab-index-template {
		width: min(100% - 20px, 1180px);
	}
	.lab-button,
	.lab-admin-link,
	.lab-footer-link {
		width: 100%;
		box-sizing: border-box;
	}
}
